const $=s=>document.querySelector(s);$('#compare').addEventListener('input',e=>$('.compare').style.setProperty('--pos',e.target.value+'%'));document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d&& (e.offsetX<0||e.offsetY<0||e.offsetX>d.clientWidth||e.offsetY>d.clientHeight))d.close()}));$('#book').onclick=()=>window.openProjectBrief();